// src/pages/AdminDashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Adjust the path to your actual location

const AdminDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      // Call the logout function from api.js
      const message = await logout();
      console.log(message); // Optional: log the successful logout message to the console

      // Remove the token from localStorage (or cookies)
      localStorage.removeItem('token');

      // Redirect to the login page
      navigate('/login'); // Use navigate to redirect to the login page
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <div>
      <h1>Admin Dashboard</h1>
      <button onClick={() => navigate('/create-user')}>Create User</button>
      <button onClick={() => navigate('/exam-data')}>Manage Exam Data</button>
      
      {/* Logout button */}
      <button onClick={handleLogout}>Logout</button>
    </div>
  );
};

export default AdminDashboard;
